'use client';

import { useEffect, useRef, useState } from 'react';
import { usePlayback } from './use-playback';
import { useReducedMotion } from './use-reduced-motion';
import './svg-wave-divider.css';

export interface SvgWaveDividerProps {
  /** Peak height of the wave, in pixels (kept within the divider's height). */
  amplitude?: number;
  /** Wave cycles per second. */
  speed?: number;
  /** Fixed height of the divider, in pixels. */
  height?: number;
  /** Color of the section below the divider. */
  fill?: string;
  paused?: boolean;
  className?: string;
}

/**
 * A shallow, moving wave between two sections. Its height never changes, so
 * nothing around it shifts. Paused, off screen, hidden or with reduced
 * motion it holds a still curve.
 */
export function SvgWaveDivider({
  amplitude = 10,
  speed = 0.25,
  height = 48,
  fill = '#eaf2fb',
  paused = false,
  className = '',
}: SvgWaveDividerProps) {
  const root = useRef<SVGSVGElement>(null);
  const reduced = useReducedMotion();
  const playing = usePlayback(root, paused || reduced);
  const [phase, setPhase] = useState(0);
  const amp = Math.min(amplitude, height / 2 - 2);

  useEffect(() => {
    if (!playing) return;
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      setPhase(
        (p) => (p + ((now - last) / 1000) * speed * Math.PI * 2) % (Math.PI * 2)
      );
      last = now;
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [playing, speed]);

  const W = 400;
  const mid = height / 2;
  const points = Array.from({ length: 41 }, (_, i) => {
    const x = (i / 40) * W;
    const y = mid + Math.sin((i / 40) * Math.PI * 4 + phase) * amp;
    return `${x.toFixed(1)} ${y.toFixed(1)}`;
  });

  return (
    <svg
      ref={root}
      className={`mg-wave ${className}`}
      viewBox={`0 0 ${W} ${height}`}
      preserveAspectRatio='none'
      style={{ height }}
      aria-hidden='true'
    >
      <path
        d={`M${points.join(' L')} L${W} ${height} L0 ${height}Z`}
        fill={fill}
      />
    </svg>
  );
}

.mg-wave {
  display: block;
  width: 100%;
  /* Sits flush on the section below it. */
  margin-bottom: -1px;
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
